mapper.select:
/* selectHoliday - Lee JiSeob */
SELECT SCHDL_NM AS HOLIDAY_NAME, BGNG_YMD AS START_DATE, END_YMD AS END_DATE
FROM SAB900 /* 공휴일 정보 */ WHERE UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}


        /* selectDuplicate - Lee JiSeob */

		SELECT
			COUNT(*) AS CNT

		FROM
			SAB900 /* 공휴일 정보 */

		WHERE
			SCHDL_NM = #{HOLIDAY_NAME}
			AND BGNG_YMD = #{START_DATE}
			AND END_YMD = #{END_DATE}

mapper.update:

        /* updateHolidaySeparate - Lee JiSeob */

		UPDATE SAB900 /* 공휴일 정보 */
		SET
			SCHDL_NM = #{HOLIDAY_NAME}, 
            BGNG_YMD = #{START_DATE}, 
            END_YMD = #{END_DATE},
			LAST_MDFR_ID = #{USER_ID},
			LAST_MDFCN_DT = SYSDATE

		WHERE
			SCHDL_NM = #{PREV_HOLIDAY_NAME}
            AND BGNG_YMD = #{PREV_START_DATE}
            AND END_YMD = #{PREV_END_DATE}


        /* deleteHolidaySeparate - Lee JiSeob */

		DELETE FROM SAB900 /* 공휴일 정보 */

		WHERE
			SCHDL_NM = #{PREV_HOLIDAY_NAME}
            AND BGNG_YMD = #{PREV_START_DATE}
            AND END_YMD = #{PREV_END_DATE}
